"""Decoder/replay checks against frames generated by the kernel C encoder."""
import binascii
import json
from pathlib import Path
import struct
import subprocess
import sys
import tempfile
import unittest

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "scripts"))
from telemetry import Decoder, FRAME_SIZE, SequenceTracker

FIXTURE = Path("build/tests/telemetry.bin").read_bytes()


class TelemetryTests(unittest.TestCase):
    def test_cross_language(self):
        decoder = Decoder()
        records = decoder.feed(FIXTURE)
        self.assertEqual([r["record_sequence"] for r in records], [1, 2, 4])
        self.assertEqual([r["target_ms"] for r in records], [100, 200, 400])
        self.assertEqual([r["distance_mm"] for r in records], [2000, 9999, 9999])
        self.assertEqual(records[-1]["telemetry_dropped"], 1)
        self.assertEqual(records[0]["controller_sequence"], 1)
        self.assertEqual(records[0]["decision_at_ms"], 100)
        self.assertEqual(records[0]["target_speed_mm_s"], 200)
        self.assertEqual(decoder.bad_crc, 0)
        self.assertEqual(binascii.crc_hqx(b"123456789", 0xffff), 0x29b1)

    def test_every_split(self):
        for split in range(len(FIXTURE) + 1):
            decoder = Decoder()
            records = decoder.feed(FIXTURE[:split]) + decoder.feed(FIXTURE[split:])
            self.assertEqual(len(records), 3)
            self.assertFalse(decoder.buffer)
        decoder = Decoder()
        records = []
        for byte in FIXTURE:
            records += decoder.feed(bytes([byte]))
        self.assertEqual(len(records), 3)

    def test_corruption_and_recovery(self):
        damaged = bytearray(FIXTURE[:FRAME_SIZE])
        damaged[24] ^= 0x80
        decoder = Decoder()
        records = decoder.feed(b"junk\xa5" + damaged + FIXTURE[FRAME_SIZE:])
        self.assertEqual([r["record_sequence"] for r in records], [2, 4])
        self.assertEqual(decoder.bad_crc, 1)
        self.assertGreater(decoder.discarded_bytes, 0)
        invalid = bytearray(FIXTURE[:FRAME_SIZE])
        invalid[4:6] = b"\xff\xff" # Bogus length must not make decoder wait forever.
        decoder = Decoder()
        self.assertEqual(len(decoder.feed(invalid + FIXTURE)), 3)
        self.assertGreater(decoder.bad_header, 0)
        for offset in range(1, FRAME_SIZE):
            decoder = Decoder()
            self.assertEqual(len(decoder.feed(FIXTURE[offset:])), 2)
        decoder = Decoder()
        decoder.feed(b"x" * 100000 + b"\xa5")
        self.assertEqual(decoder.buffer, b"\xa5")
        self.assertEqual(len(decoder.feed(FIXTURE[1:])), 3)

    def test_sequence_and_reset(self):
        tracker = SequenceTracker()
        for sequence, timestamp in [(0xffffffff, 100), (0, 200), (2, 300)]:
            self.assertFalse(tracker.accept(dict(record_sequence=sequence, target_ms=timestamp)))
        self.assertEqual(tracker.missing, 1)
        self.assertFalse(tracker.accept(dict(record_sequence=2, target_ms=300)))
        self.assertEqual(tracker.duplicates, 1)
        self.assertTrue(tracker.accept(dict(record_sequence=1, target_ms=100)))
        self.assertEqual(tracker.missing, 0)

    def test_record_and_replay(self):
        with tempfile.TemporaryDirectory() as directory:
            recording = Path(directory) / "session.jsonl"
            result = subprocess.run([sys.executable, "scripts/telemetry_view.py", "--input",
                "build/tests/telemetry.bin", "--plain", "--record", str(recording)],
                text=True, capture_output=True, check=True)
            events = [json.loads(line) for line in recording.read_text().splitlines()]
            self.assertEqual(events[0]["kind"], "session")
            self.assertEqual(len(events), 4)
            self.assertEqual(events[-1]["rx_missing"], 1)
            self.assertIn("host_monotonic_ns", events[-1])
            replay = subprocess.run([sys.executable, "scripts/telemetry_view.py", "--replay",
                str(recording), "--plain", "--speed", "10000"],
                text=True, capture_output=True, check=True)
            self.assertEqual(replay.stdout, result.stdout)
            duplicate = subprocess.run([sys.executable, "scripts/telemetry_view.py", "--input",
                "build/tests/telemetry.bin", "--record", str(recording)], capture_output=True)
            self.assertNotEqual(duplicate.returncode, 0) # Existing recordings are not overwritten.


if __name__ == "__main__":
    unittest.main()
